def mc(prompt,answer,wrong,explanation,evidence='',basis='source'):
 opts=[answer]+wrong;assert len(opts)==len(set(opts))
 k=int(hashlib.sha256((prompt+answer).encode()).hexdigest()[:5],16)%len(opts);opts=opts[k:]+opts[:k]
 return dict(kind='choice',prompt=prompt,answer=answer,options=opts,explanation=explanation,evidence=evidence,basis=basis)
def response(prompt,model,**kw):return dict(kind='response',prompt=prompt,model=model,**kw)
def form(c,n):
 fields=[dict(id='name',label='Fictional full name',example='Alex Morgan',required=True),dict(id='reference',label='Reference code from the case',example=c['code'],expected=c['code'],required=True),dict(id='date',label='Session date (copy the full date)',example=c['date'],expected=c['date'],required=True)]
 if n>=2:fields+=[dict(id='reason',label='Reason for contacting the service',example=c['problem'],required=True)]
 if n>=3:fields+=[dict(id='method',label='Reply method',options=['Email','Phone'],example='Email',required=True),dict(id='email',label='Fictional reply email (required if Email is selected)',example='alex@example.invalid',required_if={'field':'method','value':'Email'}),dict(id='phone',label='Fictional reply phone (required if Phone is selected)',example='020 7946 0123',required_if={'field':'method','value':'Phone'})]
 if n>=4:fields+=[dict(id='availability',label='Give two suitable dates or explain a timing restriction',example='I am available on Saturdays. Please offer two possible dates.',required=True)]
 if n>=5:fields+=[dict(id='support',label='If equipment or access support is needed, explain it; otherwise write not needed',example='I need access to a computer at the office.',required=True),dict(id='declaration',label='Check consistency and type: I checked these fictional details',example='I checked these fictional details',required=True)]
 return dict(kind='form',prompt='Complete the practice form. Use the case reference and fictional personal details. Follow conditional fields.',fields=fields,model='Read the labels, follow the stated conditions and check consistency. Examples are fictional; this form is not sent to a service.')
def make_case(n,s,i):
 c=TOPICS[i].copy();d=date(2027,1,4)+timedelta(days=(s-1)*7+i);c.update(date=d.strftime('%A %d %B %Y'),short_date=d.strftime('%d %B'),deadline=(d-timedelta(days=1)).strftime('%A %d %B %Y')+' at 18:00',time=f'{9+(i+s)%7}:30',room=str(1+(s+i)%8),code=f'BE-{n}{s}{i+1:02d}')
 return c
def glossary(c):return sorted(dict([('available','free or ready to be used'),(c['word'],c['definition']),('session','a period of time used for a particular activity'),('support','help given to someone')]).items())
def third_reason(c):return re.sub(r'\bme\b','them',c['reason'].replace('I am','the user is').replace('I would','the user would').replace('I can','the user can').replace('I will','the user will'))
def base_material(c,n,s):
 notice=f"{c['place']}\n{c['event'].capitalize()}\n{c['date']} at {c['time']}\nRoom {c['room']}\nBring your {c['item']}.\nContact: {c['name']}\nReference: {c['code']}"
 instructions=f"INSTRUCTIONS\n1. First, read your confirmation.\n2. Then bring your {c['item']} to Room {c['room']}.\n3. Check your details before leaving.\nIf you cannot attend on {c['date']}, contact {c['name']} before {c['deadline']}. Do not wait until after the session."
 story=f"A SHORT ACCOUNT\n{c['past']} Later, I spoke to {c['name']} at {c['place']}. We arranged a {c['event']} for {c['date']} at {c['time']}. Finally, I copied the reference {c['code']} so that I could find the arrangement again."
 choices=f"OPTIONS\nOption A: {c['choice']}. The user prefers this option because {third_reason(c)}.\nOption B: {c['other']}. This remains an alternative; ask the service about its availability."
 formal=f"EMAIL\nDear {c['name']},\n\n{c['problem']} I would like to {c['goal']}. Please confirm the session on {c['date']} at {c['time']}, in Room {c['room']}. I will bring my {c['item']}. Is there anything else I should prepare?\n\nKind regards,\nAlex Morgan"
 friendly=f"MESSAGE TO A FRIEND\nHi Sam, I need to {c['goal']}. {c['problem']} I am going to {c['place']} on {c['date']} at {c['time']}. Can we talk afterwards? Thanks, Alex."
 if n==1:
  if s==2:return f"ABOUT ALEX\nMy name is Alex. I am at {c['place']}. I would like to {c['goal']}. I will bring my {c['item']}. My session is on {c['short_date']} at {c['time']}."
  if s==6:return f"MESSAGE\nHello Alex. Please come to {c['place']} on {c['short_date']} at {c['time']}. Bring your {c['item']}. Ask for {c['name']}. Thank you."
  return notice
 if n==2:return [formal,story,notice,instructions,formal,notice,formal][s-1]+'\n\n'+(choices+'\n\n'+instructions if s==7 else choices if s==1 else instructions if s==6 else '')
 if n==3:return [story,formal+'\n\n'+friendly,choices+'\n\n'+formal,instructions,formal,story,instructions+'\n\n'+formal][s-1]
 report=f"REPORT: {c['event'].upper()}\n\n1. Purpose\nThe fictional {c['place']} is comparing ways for people to {c['goal'].replace('my ','their ')}. The case below concerns one user; it does not describe every user.\n\n2. Case and arrangements\nThe user says: '{c['problem']}' The user has a session on {c['date']} at {c['time']}, in Room {c['room']}. Their reference is {c['code']}. {choices}\n\n3. Evidence\nIn a fictional trial, 18 of 24 people completed a booking. Six did not. Only 12 of the 18 who completed a booking returned a feedback form. Nine of those 12 said the instructions were clear. The report does not record why the six people could not complete a booking.\n\n4. Recommendation\nThe coordinator believes the trial is promising, but the sample is small. The service should ask people who did not complete a booking about the barriers they experienced before deciding whether the arrangements should continue.\n\n5. Procedure\n{instructions}"
 source_b=f"SOURCE B: VOLUNTEER LETTER\n\nI welcome choice at {c['place']}, but I do not think 9 positive replies prove that all users can get support. We have heard from only half of the 24 people who tried to book. People who did not complete a booking may have different experiences. I recommend keeping both routes during a longer trial and asking those users what prevented them from taking part.\n\nThis is the volunteer's interpretation of the same trial figures, not a second independent survey."
 if n==4:return [story+'\n\n'+choices,report,instructions+'\n\n'+formal,formal+'\n\n'+friendly,report,report,report+'\n\n'+source_b][s-1]
 return report+('\n\n'+source_b if s in [3,4,7] else '')
def visuals(c,i):
 labels=['Station','Library','School','College','You are here','Clinic','Shop','Office','Sports centre']
 # Four neighbouring labels vary with context without changing the compass convention.
 adjacent=['Library','College','Clinic','Office'];shift=i%4;adjacent=adjacent[shift:]+adjacent[:shift]
 labels[1],labels[3],labels[5],labels[7]=adjacent
 return dict(kind='map',caption='Practice map: north is up. Each square is one block; directions refer to adjacent squares.',columns=['West','Centre','East'],rows=[labels[0:3],labels[3:6],labels[6:9]],north=labels[1],south=labels[7])
def reading(c,n,s,i):
 text=base_material(c,n,s);visual=None
 tasks=[]
