 if s in [5,6] and n>=2:tasks+=[mc('Which glossary headword comes first alphabetically?',g[0][0],[g[1][0],g[2][0]],'Compare letters from left to right until they differ.',g[0][0])]
 # Context details are secondary checks, not the entire teaching activity.
